# ---------- picture builders ----------
DEFS = ('<defs><marker id="ah" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto">'
        '<path d="M0,0 L10,5 L0,10 z" fill="#000"/></marker></defs>')
def node(label, x, y, w, h=44, shape='rect', fill='#fff', stroke='#000'):
    rx = h / 2 if shape == 'stadium' else 0
    return ('<g class="nd"><rect x="%s" y="%s" width="%s" height="%s" rx="%s" fill="%s" stroke="%s" stroke-width="1.6"/>'
            '<text x="%s" y="%s" text-anchor="middle" font-size="14" fill="#000">%s</text></g>' % (x, y, w, h, rx, fill, stroke, x + w / 2, y + h / 2 + 5, label))
def region(label, x, y, w, h, dash='none'):
    return ('<g><rect x="%s" y="%s" width="%s" height="%s" fill="none" stroke="#000" stroke-width="1" stroke-dasharray="%s"/>'
            '<text x="%s" y="%s" font-size="12" fill="#000">%s</text></g>' % (x, y, w, h, dash, x + 10, y + 16, label))
def edge(x0, y0, x1, y1, dash=None, arrow=True, curve=False):
    d = 'M%s,%s C%s,%s %s,%s %s,%s' % (x0, y0, x0 + 10, y0 - 25, x1 - 10, y1 - 25, x1, y1) if curve else 'M%s,%s L%s,%s' % (x0, y0, x1, y1)
    return '<path d="%s" fill="none" stroke="#000" stroke-width="1.6"%s%s/>' % (d, ' stroke-dasharray="%s"' % dash if dash else '', ' marker-end="url(#ah)"' if arrow else '')
def label_text(t, x, y): return '<text x="%s" y="%s" font-size="12" fill="#000">%s</text>' % (x, y, t)
def svg(w, h, body): return '<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="%d" viewBox="0 0 %d %d" style="background:#fff">%s%s</svg>' % (w, h, w, h, DEFS, body)
def page(w, h, body, css='', script=''):
    return ('<!doctype html><html><head><meta charset="utf-8"><title>d</title><style>body{margin:0;background:#fff}%s</style></head><body>%s<script>%s</script></body></html>'
            % (css, svg(w, h, body), script))

def gc1(lvl='F', pay_fill=None, curve_edge=None, dashed_edge=None, reverse=False, chain=False, notify='배송 완료 알림', purple=False, extra='', region_dash='none'):
    ns, es = [], []
    ns.append(node('주문', 20, 60, 110, shape='stadium')); ns.append(node('재고 확인', 170, 60, 110, fill=pay_fill or '#fff'))
    if lvl == 'L0':
        ns.append(node('결제', 320, 60, 140)); xs = 500
        pairs = [(130, 280), (280, 320), (460, 500)]
        es = [edge(130, 82, 170, 82), edge(280, 82, 320, 82), edge(460, 82, 500, 82)]
    else:
        auth = node('카드 인증', 340, 60, 110, stroke='#8a2be2' if False else '#000'); appr = node('승인 요청', 500, 60, 110, stroke='#8a2be2' if purple else '#000')
        reg = '' if chain else region('결제', 320, 30, 310, 104, dash=region_dash)
        if chain: ns.append(node('결제', 320, 60, 110)); auth = node('카드 인증', 470, 60, 110); appr = node('승인 요청', 620, 60, 110)
        ns += [reg, auth, appr]
        if chain:
            es = [edge(130, 82, 170, 82), edge(280, 82, 320, 82), edge(430, 82, 470, 82), edge(580, 82, 620, 82), edge(730, 82, 790, 82)]; xs = 790
        else:
            es = [edge(130, 82, 170, 82), edge(280, 82, 340, 82, dash=dashed_edge, curve=curve_edge), edge(450, 82, 500, 82), edge(610, 82, 670, 82)]; xs = 670
    ns.append(node('배송 요청', xs, 60, 110)); ns.append(node(notify, xs + 160, 60, 150))
    es.append(edge(xs + 110, 82, xs + 160, 82))
    if reverse: es.append(edge(xs + 55, 104, 375, 104) if False else '<path d="M%s,104 L%s,140 L375,140 L375,104" fill="none" stroke="#000" marker-end="url(#ah)"/>' % (xs + 55, xs + 55))
    return svg(xs + 340, 170, ''.join(ns + es) + extra)

def gc3(groups=None, marker='', rdash='none', sizes=None):
    srcs = ['주문 DB', '회원 DB', '재고 DB', '결제 로그', '배송 로그', '앱 로그', '웹 로그', '광고 API', '날씨 API', '환율 API', 'CRM', '고객센터 티켓']
    sizes = (sizes or [3, 4, 3, 2]) if groups else [12]; names = groups or ['']
    body, y, i = [], 40, 0
    for g, n in enumerate(sizes):
        top = y
        for s in srcs[i:i + n]:
            body.append(node(s, 20, y, 150, 30)); body.append(edge(170, y + 15, 330, 342)); y += 42
        if groups: body.append(region(names[g] + marker, 10, top - 26, 170, y - top + 30 + 2, dash=rdash[g] if isinstance(rdash, (list, tuple)) else rdash)); y += 30
        i += n
    h = max(y + 20, 420)
    body += [node('수집', 330, 320, 100), node('정제', 470, 320, 100), node('적재', 610, 320, 100), node('대시보드', 750, 320, 110),
             edge(430, 342, 470, 342), edge(570, 342, 610, 342), edge(710, 342, 750, 342)]
    return 900, h, ''.join(body)

def gc4(skip=None, region_over=None, hover=False, rename=None):
    A = [('결제 승인', 170, 120), ('정산', 330, 100), ('정산 보고서', 470, 130)]
    B = [('출고', 170, 100), ('배송 추적', 310, 110), ('배송 완료', 460, 110), ('리뷰 요청', 610, 110), ('리뷰', 760, 90), ('평점 반영', 890, 110), ('상품 평점', 1040, 110)]
    body = [node('주문', 20, 110, 100, shape='stadium')]
    def row(items, y, root):
        prev = None
        items = [i for i in items if i[0] != skip]
        for k, (l, x, w) in enumerate(items):
            body.append(node((rename or {}).get(l, l), x, y, w))
            if k == 0: body.append(edge(120, 132, x, y + 22))
            elif prev: body.append(edge(prev[1] + prev[2], y + 22, x, y + 22))
            prev = (l, x, w)
        return items
    row(A, 40, 1); b = row(B, 190, 1)
    if skip == '평점 반영': body.append(edge(850, 212, 1040, 212))
    if region_over: body.insert(1, region(region_over, 740, 170, 380, 84))
    return 1200, 280, ''.join(body)

# ---------- run directory builder ----------
def make_run(name, case, turns, files, rid=None, request=None):
    d = os.path.join(ROOT, name)
    shutil.rmtree(d, ignore_errors=True); os.makedirs(d)
    for rel, content in files.items():
        p = os.path.join(d, rel); os.makedirs(os.path.dirname(p), exist_ok=True); open(p, 'w', encoding='utf-8').write(content)
    P = lambda rel: '/private/tmp/drd-eval/%s/%s' % (name, rel)
    run = dict(run_id=name, case=case, arm='fixture', effort='-', model='-', rep=1, turns=[])
    if request: run['request'] = request
    for i, t in enumerate(turns, 1):
        text = t['text'].replace('{P}', '').format(*[P(r) for r in t.get('paths', [])]) if t.get('paths') else t['text']
        r = dict(turn=i, input='', output=text, cost=0, classifier=dict(asks_human=bool(t.get('ask')), topic=t.get('topic')))
        if t.get('ask'): r['answer'] = t['answer']; r['answer_topic'] = t.get('topic')
        run['turns'].append(r)
        with open(os.path.join(d, 'turn%d.jsonl' % i), 'w') as f:
            f.write(json.dumps(dict(type='assistant', message=dict(content=[dict(type='text', text=text)]))) + '\n')
    json.dump(run, open(os.path.join(d, 'run.json'), 'w'), ensure_ascii=False, indent=1)
    return d

OK = '좋습니다. 진행해 주세요'
def gc1_run(name, f_svg, extra_turn1=None, final='도식을 그렸습니다. {0} 결제는 실선 테두리 영역으로 묶었습니다. 흐름은 화살촉이 있는 실선입니다.', two=True, files=None, s1=None, answer=OK):
    fl = {'out/L0.svg': s1 or gc1('L0'), 'out/F.svg': f_svg}
    fl.update(files or {})
    t = [dict(text='가장 간단한 L0 입니다. {0} 고칠 부분이 있나요? 이대로 진행할까요?', paths=['out/L0.svg'], ask=True, topic='l0_or_render_feedback', answer=answer),
         dict(text=final, paths=['out/F.svg'])] if two else [dict(text=final, paths=['out/F.svg'])]
    return make_run(name, 'GC-1', t, fl)

def gc4_run(name, f_html, turns=None, files=None, s1=None, final='도식입니다. {0}'):
    fl = {'out/F.html': f_html}; fl.update(files or {})
    return make_run(name, 'GC-4', turns or [dict(text=final, paths=['out/F.html'])], fl)

